# frozen_string_literal: true

require "json"

RSpec.describe DaisyUI::Tailwind::Sources do
  subject(:sources) { described_class.new(manifest, components, **options) }

  let(:manifest)     { DaisyUI::Tailwind::Manifest.load }
  let(:components)   { %w[Button Card] }
  let(:options)      { {} }
  let(:inline_lines) { sources.to_css.lines.grep(/\A@source inline/) }

  def inline_classes(line) = line[/inline\("(.*)"\);/, 1].split

  describe "#to_css" do
    it "starts with a header naming the generator and the components" do
      expect(sources.to_css).to start_with(
        "/* Generated by daisyui-tailwind (daisyui #{DaisyUI::VERSION}): do not edit. */\n" \
        "/* daisyUI components: Button, Card */\n"
      )
    end

    it "writes one @source inline per component after base.rb's shared classes" do
      expect(inline_lines.size).to eq(3)
      expect(inline_classes(inline_lines[0])).to eq(manifest.shared["classes"])
      expect(inline_classes(inline_lines[1])).to eq(manifest.components["Button"]["classes"])
      expect(inline_classes(inline_lines[2])).to eq(manifest.components["Card"]["classes"])
    end

    it "labels each line with its component" do
      expect(sources.to_css).to include("/* DaisyUI::Button */\n@source inline(\"btn ")
    end

    context "without components" do
      let(:components) { [] }

      it "says so, and gives Tailwind nothing" do
        expect(sources.to_css).to include("/* No DaisyUI components referenced. */")
        expect(sources.to_css).not_to include("@source")
      end
    end

    context "with responsive breakpoints" do
      let(:options) { { responsive: %w[sm @lg] } }

      it "adds each breakpoint to the component class and its modifiers, the classes `responsive:` renders" do
        button = inline_classes(inline_lines[1])

        expect(button).to include("btn", "sm:btn", "@lg:btn", "sm:btn-primary", "@lg:btn-lg")
        expect(inline_classes(inline_lines[0])).to include("sm:skeleton")
        expect(inline_classes(inline_lines[2])).to include("card-body", "sm:card-side")
        expect(inline_classes(inline_lines[2])).not_to include("sm:card-body")
      end
    end

    context "with an invalid breakpoint" do
      let(:options) { { responsive: ["sm:"] } }

      it "raises" do
        expect { sources }.to raise_error(ArgumentError, /breakpoint "sm:"/)
      end
    end

    context "with a prefix" do
      let(:options) { { prefix: "d-", responsive: %w[md] } }

      it "prefixes every class the way DaisyUI.configuration.prefix renders them" do
        button = inline_classes(inline_lines[1])

        expect(button).to include("d-btn", "d-btn-primary", "md:d-btn-primary")
        expect(button).not_to include("btn")
      end
    end
  end

  describe "#to_json" do
    subject(:json) { JSON.parse(sources.to_json) }

    it "lists the components with absolute files, plus every class and file together" do
      expect(json["daisyui"]).to eq(DaisyUI::VERSION)
      expect(json["components"].keys).to eq(%w[Button Card])
      expect(json["components"]["Button"]).to include(
        "class" => "DaisyUI::Button",
        "name" => "btn",
        "files" => [File.join(DaisyUI::Tailwind::ROOT, "lib/daisy_ui/button.rb")]
      )
      expect(json["shared"]["files"]).to eq([File.join(DaisyUI::Tailwind::ROOT, "lib/daisy_ui/base.rb")])
      expect(json["classes"]).to include("btn", "card-body", "skeleton")
      expect(json["classes"]).to eq(json["classes"].uniq.sort)
      expect(json["files"]).to all(satisfy { |path| File.file?(path) })
      expect(json["files"].size).to eq(3)
    end
  end

  describe "#render" do
    it "renders :css or :json and rejects anything else" do
      expect(sources.render(:css)).to eq(sources.to_css)
      expect(sources.render("json")).to eq(sources.to_json)
      expect { sources.render(:yaml) }.to raise_error(ArgumentError, /format/)
    end
  end
end
